def replace_params(path: str, param_convertors: dict[str, Convertor[typing.
    Any]], path_params: dict[str, str]) ->tuple[str, dict[str, str]]:
    for key, convertor in list(param_convertors.items()):
        value = path_params.get(key)
        if value is None:
            continue
        if key in path_params:
            converted = convertor.to_string(value)
            assert convertor.regex.fullmatch(converted), f"Path parameter '{key}' with value '{converted}' did not match the expected format."
            path = path.replace("{" + key + "}", converted)
            path_params = {k: v for k, v in path_params.items() if k != key}
    return path, path_params

def __init__(self, host: str, app: ASGIApp, name: (str | None)=None) ->None:
    assert not host.startswith("/"), "Host must not start with '/'"
    self.host = host
    self.app = app
    self.name = name
    self.host_regex, self.host_format, self.param_convertors = compile_path(host)

def url_path_for(self, name: str, /, **path_params: typing.Any) ->URLPath:
    for route in self.routes:
        try:
            return route.url_path_for(name, **path_params)
        except NoMatchFound:
            pass
    raise NoMatchFound(name, path_params)
